#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-12

# strict-mode: opt-out this harness counts failures and reports a summary, so
# `-e` would abort on the first failing assertion and hide the rest. Same shape
# as tests/plugins/test-hooks-manifest-mirror.sh. `set -uo pipefail` is set below.
#
# =============================================================================
# The shipped hooks plugin must not carry test and build tooling configs (#4030)
# =============================================================================
# scripts/build-plugins.sh rsyncs src/hooks/ into plugins/ork/hooks/ with an
# exclude list that drops test SOURCES (`__tests__`, `*.d.ts`, `*.map`) but
# kept the configs of those same tests: vitest.*.ts, tsconfig*.json and
# esbuild.config.mjs shipped to every install. Nothing inside an installed
# plugin runs them (Claude Code reads hooks.json and executes bin/run-hook.mjs
# against the prebuilt dist/ bundles; the mirror package.json scripts are never
# invoked), and they reference devDependencies the mirror no longer declares.
#
# This test is the ratchet, same two halves as the #3971 mirror test:
#
#   A. the shipped tree carries none of the seven configs while still carrying
#      the files that ARE load-bearing (bin/run-hook.mjs, hooks.json,
#      package.json), so the test cannot pass by wiping the mirror;
#   B. a POSITIVE CONTROL that extracts the real exclude list from
#      build-plugins.sh and dry-run rsyncs src/hooks/ into a temp dir, then
#      asserts no forbidden name appears in the file list. Without B the test
#      would still pass if the excludes were removed and someone hand-deleted
#      the mirror files once, which is the failure mode #3971 documented.
#
# rsync dialects: macOS ships openrsync, CI runs GNU rsync on Linux. Both are
# SILENT about the file list without -v, and both wrap the list between
# dialect-specific banners ("Transfer starting: N files" on openrsync only)
# and a shared trailing summary ("sent N bytes ...", "total size is ...").
# With `-a -n -v` both print one plain filename per line, so the checks below
# grep for FILENAMES and strip every banner/summary line by prefix; no
# dialect-specific format (no --itemize-changes escapes, no openrsync-only
# fields) is parsed.
# =============================================================================

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
cd "$REPO_ROOT"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; NC=$'\033[0m'
PASS=0; FAIL=0
pass() { echo "  ${GREEN}PASS${NC} $1"; PASS=$((PASS + 1)); }
fail() { echo "  ${RED}FAIL${NC} $1"; FAIL=$((FAIL + 1)); }

MIRROR="plugins/ork/hooks"
SOURCE="src/hooks"

# The seven files #4030 lists. `vitest.*.ts` plus the explicit `vitest.config.ts`
# cover the four vitest configs; `tsconfig*.json` covers both tsconfigs.
FORBIDDEN=(
    vitest.config.ts
    vitest.bench.config.ts
    vitest.property.config.ts
    vitest.setup.ts
    tsconfig.json
    tsconfig.test.json
    esbuild.config.mjs
)

echo "=========================================="
echo "  hooks test-config exclusion (#4030)"
echo "=========================================="

# ─── A. the shipped tree ────────────────────────────────────────────
if [[ ! -d "$MIRROR" ]]; then
    fail "$MIRROR/ is missing entirely (run npm run build)"
else
    # Positive controls: the mirror must still be a real, load-bearing plugin.
    for real_file in bin/run-hook.mjs hooks.json package.json; do
        if [[ -f "$MIRROR/$real_file" ]]; then
            pass "shipped tree still carries $real_file"
        else
            fail "shipped tree is missing $real_file (run npm run build; deleting the tree is not the fix)"
        fi
    done

    for f in "${FORBIDDEN[@]}"; do
        if [[ -e "$MIRROR/$f" ]]; then
            fail "shipped plugin carries test/build config $f (add it to the build-plugins.sh exclude list, #4030)"
        else
            pass "shipped tree does not carry $f"
        fi
    done
fi

# ─── B. positive control: the real exclude list, exercised ─────────
# Locate the hooks rsync block in build-plugins.sh and extract its excludes.
START=$(grep -n 'rsync -a \\' scripts/build-plugins.sh | head -1 | cut -d: -f1)
if [[ -z "$START" ]]; then
    fail "cannot find the hooks rsync block in scripts/build-plugins.sh"
else
    # The block runs while lines end with a continuation backslash; the first
    # line after START that does not is the rsync destination.
    END=$(awk -v s="$START" 'NR>s && !/\\$/{print NR; exit}' scripts/build-plugins.sh)
    if [[ -z "$END" ]]; then
        fail "cannot find the end of the hooks rsync block in scripts/build-plugins.sh"
    else
        EXCLUDES=$(sed -n "$((START + 1)),$((END - 1))p" scripts/build-plugins.sh \
            | grep -o -- "--exclude='[^']*'" \
            | sed "s/--exclude='//; s/'$//")

        if [[ -z "$EXCLUDES" ]]; then
            fail "extracted an empty exclude list from the hooks rsync block (extraction is broken, not the build)"
        else
            EXCLUDE_COUNT=$(printf '%s\n' "$EXCLUDES" | wc -l | tr -d ' ')
            if [[ "$EXCLUDE_COUNT" -lt 10 ]]; then
                fail "exclude list looks truncated ($EXCLUDE_COUNT entries, expected at least 10)"
            else
                pass "extracted $EXCLUDE_COUNT excludes from the hooks rsync block"
            fi

            # Dry-run the actual rsync with the actual excludes into a temp dir.
            TMP="$(mktemp -d)"
            trap 'rm -rf "$TMP"' EXIT
            printf '%s\n' "$EXCLUDES" > "$TMP/excludes"
            RSYNC_ARGS=()
            while IFS= read -r pat; do
                [[ -n "$pat" ]] && RSYNC_ARGS+=(--exclude="$pat")
            done < "$TMP/excludes"
            # silent: stderr is captured to $TMP/err and printed verbatim on failure below
            rsync -a -n -v "${RSYNC_ARGS[@]}" "$SOURCE/" "$TMP/hooks/" > "$TMP/raw" 2> "$TMP/err"
            RSYNC_RC=$?

            if [[ $RSYNC_RC -ne 0 ]]; then
                fail "rsync dry run failed (rc=$RSYNC_RC)"
                cat "$TMP/err"
            else
                # Keep one-plain-filename-per-line only: drop both dialects'
                # banner/summary lines by prefix (openrsync "Transfer starting:",
                # both "sent N bytes ...", "total size is ...", blank lines).
                grep -v -E '^(sent |total size |Transfer starting:|$)' "$TMP/raw" > "$TMP/list"

                if [[ ! -s "$TMP/list" ]]; then
                    fail "rsync dry-run produced no file list under -v (dialect changed? inspect raw output)"
                    cat "$TMP/raw"
                else
                    # Positive: real payload files still pass the filter.
                    for real_file in bin/run-hook.mjs hooks.json package.json; do
                        if grep -Eq "(^|/)${real_file}$" "$TMP/list"; then
                            pass "dry-run list still includes $real_file"
                        else
                            fail "dry-run list is missing $real_file (the exclude list would gut the shipped plugin)"
                        fi
                    done

                    # Negative: no forbidden config survives the filter.
                    FORBIDDEN_RE='(^|/)(vitest\.bench\.config\.ts|vitest\.config\.ts|vitest\.property\.config\.ts|vitest\.setup\.ts|tsconfig\.json|tsconfig\.test\.json|esbuild\.config\.mjs)$'
                    if grep -E "$FORBIDDEN_RE" "$TMP/list" > "$TMP/hits"; then
                        while IFS= read -r hit; do
                            fail "dry-run rsync from src/hooks still emits $hit (remove the matching exclude, #4030 regressed)"
                        done < "$TMP/hits"
                    else
                        pass "dry-run rsync emits none of the seven test/build configs"
                    fi
                fi
            fi
        fi
    fi
fi

echo "=========================================="
echo "  Passed: $PASS  Failed: $FAIL"
echo "=========================================="
[[ $FAIL -eq 0 ]]
